correction.fr:
Principes clés : noms explicites, validation immédiate (TypeError/ValueError), messages d’erreur actionnables (indiquer la valeur reçue et le format attendu). Exemple fonctionnel réutilisable :

from datetime import datetime

def _ensure_non_empty_str(name: str, value):
    if not isinstance(value, str):
        raise TypeError(f"{name} must be a str, got {type(value).__name__}")
    if value.strip() == "":
        raise ValueError(f"{name} cannot be empty or whitespace")

def get_current_datetime(date_format: str = "%Y%m%d %H:%M:%S") -> str:
    _ensure_non_empty_str("date_format", date_format)
    try:
        return datetime.now().strftime(date_format)
    except Exception as exc:
        # strftime raises ValueError on bad format codes in some implementations
        raise ValueError(
            f"Invalid date_format '{date_format}'. Use strftime format tokens like '%Y-%m-%d %H:%M:%S'."
        ) from exc

def parse_date(date_str: str, date_format: str = "%Y-%m-%d") -> datetime:
    _ensure_non_empty_str("date_str", date_str)
    _ensure_non_empty_str("date_format", date_format)
    try:
        return datetime.strptime(date_str, date_format)
    except ValueError as exc:
        raise ValueError(
            f"Cannot parse date_str='{date_str}' with date_format='{date_format}'. "
            f"Expected example: {datetime.now().strftime(date_format)}"
        ) from exc

Points qu’une bonne réponse couvrirait :
- vérifications de type et contenu (non vide) ;
- messages indiquant la valeur reçue et le format attendu ;
- levée immédiate d’erreurs spécifiques (TypeError vs ValueError) ;
- tests unitaires montrant cas valides et erreurs attendues.

correction.en:
Provide a deterministic loop that calls Claude repeatedly, detects structured tool requests in the assistant reply, executes the named tool from a registry, appends the tool result to the conversation, and repeats until no tool request is present. Key points:
- Require Claude to emit tool calls as a single JSON object: {"tool_use": {"name": "...", "input": {...}}}.
- Parse that JSON from the assistant reply (robust to whitespace).
- Maintain a max-iteration guard to avoid infinite loops.
- Append tool results as assistant messages so Claude can continue reasoning.

Example Python implementation (adapt to your Claude client):

```python
import json, re, datetime

# Example tool implementations
def get_current_datetime(_input):
    return {"now": datetime.datetime.utcnow().isoformat() + "Z"}

def add_duration_to_datetime(input):
    base = datetime.datetime.fromisoformat(input["datetime"].replace("Z",""))
    result = base + datetime.timedelta(days=int(input.get("days",0)))
    return {"result": result.isoformat() + "Z"}

TOOLS = {
    "get_current_datetime": get_current_datetime,
    "add_duration_to_datetime": add_duration_to_datetime,
}

def call_claude(messages):
    # Replace with actual API call; returns string assistant reply.
    # For testing, you can simulate expected JSON tool requests.
    raise NotImplementedError

def extract_tool_request(text):
    m = re.search(r'(\{.*"tool_use".*?\})', text, re.DOTALL)
    if not m: return None
    try:
        obj = json.loads(m.group(1))
        return obj.get("tool_use")
    except json.JSONDecodeError:
        return None

def run_conversation(initial_messages, max_rounds=10):
    messages = initial_messages[:]
    for _ in range(max_rounds):
        assistant_text = call_claude(messages)
        messages.append({"role":"assistant","content":assistant_text})
        tool_req = extract_tool_request(assistant_text)
        if not tool_req:
            return assistant_text  # final answer
        name = tool_req["name"]
        inp = tool_req.get("input", {})
        if name not in TOOLS:
            messages.append({"role":"system","content":f"Tool '{name}' not found."})
            return "Error: unknown tool"
        result = TOOLS[name](inp)
        messages.append({"role":"tool","name":name,"content":json.dumps(result)})
    return "Error: max rounds exceeded"
```

This pattern ensures reliable tool chaining, explicit tool-call formatting, safe parsing, and a loop exit strategy.

JSON schema (batch tool):
{
  "name": "batch",
  "description": "Run multiple tool invocations in parallel",
  "parameters": {
    "type": "object",
    "properties": {
      "invocations": {
        "type": "array",
        "items": {
          "type": "object",
          "properties": {
            "tool": { "type": "string" },
            "args": { "type": "string", "description": "JSON-encoded arguments" }
          },
          "required": ["tool","args"]
        }
      }
    },
    "required": ["invocations"]
  }
}

Node.js example implementation (working):
const tools = {
  translate: async ({text, to}) => `TRANSLATED(${to}): ${text}`,
  sum: async ({numbers}) => numbers.reduce((a,b)=>a+b,0),
  fetchUrl: async ({url}) => { /* fetch and return body */ return `fetched:${url}`; }
};

async function run_batch(invocations) {
  const promises = invocations.map(async (inv, idx) => {
    const name = inv.tool;
    const fn = tools[name];
    if (!fn) return { index: idx, tool: name, success: false, error: 'Unknown tool' };
    let args;
    try {
      args = JSON.parse(inv.args);
    } catch (err) {
      return { index: idx, tool: name, success: false, error: 'Invalid JSON args', details: err.message };
    }
    try {
      const result = await fn(args);
      return { index: idx, tool: name, success: true, result };
    } catch (err) {
      return { index: idx, tool: name, success: false, error: err.message };
    }
  });
  return Promise.all(promises); // runs all invocations in parallel
}

Usage example:
const invocations = [
  { tool: "translate", args: JSON.stringify({text:"hello",to:"es"}) },
  { tool: "sum", args: JSON.stringify({numbers:[1,2,3]}) }
];
run_batch(invocations).then(results => console.log(results));

Notes:
- Use Promise.all for parallel execution.
- Return per-invocation status (success/error) so failures don’t abort other runs.
- Validate unknown tools and JSON parse errors explicitly.

